_RESULT_MOVED = (
    "entry.result is deprecated and will be removed in a later release: read the case's parts on the "
    "entry itself, such as entry.metrics, entry.diagnostics and entry.manifest"
)


@dataclass(init=False)
class EvaluatedCase:
    """One case of a run: what the model saw, what it forecast, what happened and what was measured.

    ``history`` is the past the model was given, one column per series,
    ``future_index`` the dates it forecast, ``observed`` what happened on
    them and ``reference`` the answer key (None for your own data).
    ``forecast`` is what the model returned, None when it crashed.
    ``metrics``, ``diagnostics`` and ``manifest`` are the case's entry in the
    report, ``result.report.cases``: each metric by name, every finding, and
    the description of the case, with its ``kind`` and ``seed``. In a run made
    with ``keep_data=False``, the default of ``Pipeline.run``, the series,
    the answer key and the forecast are None; the metrics, diagnostics and
    manifest stay.

    ``case`` is the whole ``Case``, to hand to another call such as
    ``ForecastRun.from_forecasts``. ``scenario_index`` and ``seed_index``
    place the case in the run, so two identical scenarios, or two equal
    seeds, stay apart. ``result``, the old way to the metrics, diagnostics
    and manifest, still works and warns.
    """

    case: Case | None
    forecast: Forecast | None
    _result: CaseResult
    scenario_index: int
    seed_index: int

    def __init__(self, case, forecast, result, scenario_index, seed_index):
        self.case, self.forecast, self._result = case, forecast, result
        self.scenario_index, self.seed_index = scenario_index, seed_index

    @property
    def history(self):
        """The past the model was given, one column per series; None once the run dropped its data."""
        return None if self.case is None else self.case.task.history

    @property
    def future_index(self):
        """The dates the model forecast; None once the run dropped its data."""
        return None if self.case is None else self.case.task.future_index

    @property
    def observed(self):
        """What happened on the forecast dates, one column per series; None once the run dropped its data."""
        return None if self.case is None else self.case.observed

    @property
    def reference(self):
        """The answer key, a ``Reference``; None for your own data and once the run dropped its data."""
        return None if self.case is None else self.case.reference

    @property
    def metrics(self):
        """Each metric's value by name, as in the report; empty when the model crashed."""
        return self._result.metrics

    @property
    def diagnostics(self):
        """Every finding about this case, a list of ``DiagnosticResult``, as in the report."""
        return self._result.diagnostics

    @property
    def manifest(self):
        """The description of the case, as in the report: its ``kind``, ``seed`` and how it was made."""
        return self._result.manifest

    @property
    def result(self):
        """The case's entry in the report; it still works and warns: read its parts on the entry."""
        _warn_deprecated(_RESULT_MOVED)
        return self._result

    @result.setter
    def result(self, value):
        """Replace the case's entry in the report by its old name, with a warning."""
        _warn_deprecated(_RESULT_MOVED)
        self._result = value


