_RECORDED_MODEL_MOVED = (
    "ForecastRun.from_forecasts(metadata={'model': ...}) is deprecated and will be removed in a later "
    "release: use ForecastRun.from_forecasts(cases, forecasts, name=...), which names the forecasts in "
    "the report, its plots and comparisons"
)


def _checked_name(name):
    """A model's name as given: None, or a nonempty string."""
    if name is not None and (not isinstance(name, str) or not name.strip()):
        raise TypeError(
            f'name must be a nonempty string, such as name="Ridge"; got {name!r}'
        )
    return name


@dataclass
class ForecastRun:
    """What ``Pipeline.run`` returns: every case's metrics and checks, and its scorecard.

    ``scorecard`` is the run's Scorecard, ``metrics`` every case's metrics in
    one table, ``assert_passed()`` fails on a crash or a malformed forecast,
    ``to_json(path)`` saves the report, ``checks`` counts the output checks,
    and ``report`` is the JSON-ready TestReport, which holds no histories,
    observations or forecast arrays. Each entry of ``cases`` holds one
    case's parts, such as ``result.cases[0].observed``.

    ``kept_data`` says whether each case still holds its series, answer key
    and forecast. ``Pipeline.run`` drops them once every case is scored
    unless it was called with ``keep_data=True``; the scorecard keeps what it
    draws. ``plot_forecasts()`` and ``calibration()`` read
    the forecasts, so they need a run that kept them; ``plot_errors()`` reads
    only the metrics. ``titles`` optionally names each scenario position in
    plain words for the plots (a run on the scorecard's kinds of series sets
    them to the pattern and noise level); they are not saved in the report.
    ``metadata["name"]``, when the pipeline or the recorded forecasts were
    given a name, heads both plots.
    """

    cases: list[EvaluatedCase]
    metadata: dict[str, Any] = field(default_factory=dict)
    titles: list[str] = field(default_factory=list)
    kept_data: bool = True
    _card: Any = field(default=None, init=False, repr=False, compare=False)

    @classmethod
    @_renamed_keywords(scores="metrics")
    def from_forecasts(
        cls,
        cases,
        forecasts,
        *,
        name=None,
        metadata=None,
        metrics=None,
        checks=None,
        **old_arguments,
    ):
        """Check forecasts made earlier, one per case, and measure their errors, without a model.

        ``forecasts[i]`` is the forecast recorded for ``cases[i]``, in any form
        a model's ``predict`` may return: a list or NumPy array, a pandas Series
        or DataFrame, or a ``Forecast``. ``None`` means nothing was recorded,
        and that case fails "Runs without errors". Each forecast gets the output
        checks and metrics of ``Pipeline.run``, and the run's report and plots
        work as usual. ``name`` says what made the forecasts, for example
        ``name="weather service"``: it is ``result.metadata["name"]``, heads
        the plots and labels the run in a comparison, as
        ``Pipeline(..., name=...)`` does. ``metadata`` is added to the run's
        metadata, for example ``{"made_on": "2024-05-01"}``; naming the
        forecasts there with ``{"model": ...}`` still works and warns.
        ``metrics`` records more metrics and ``checks`` adds output checks of
        your own, as in ``Pipeline.run``, ``timegym.checks.dependence()``
        included. No model is kept, so these cases cannot be replayed.
        ``scores``, the old name of ``metrics``, still works and warns, and so
        do ``check_dependence``, ``n_calibration``, ``alpha`` and
        ``dependence_seed_offset``, the old form of ``dependence()``.
        """
        from timegym.diagnostics import (
            _check_requests,
            _dependence_request,
            _describe_checks,
            _describe_metrics,
            _metric_requests,
        )
        from timegym.pipeline import _as_forecast, _evaluate_ready_made
        from timegym.provenance import runtime_provenance

        if isinstance(cases, Case):
            raise TypeError("cases must be a list of Case objects, not one Case")
        if metadata is not None and not isinstance(metadata, dict):
            raise TypeError("metadata must be a dictionary or None")
        name = _checked_name(name)
        if name is not None and "name" in (metadata or {}):
            raise ValueError(
                "Give the name once: name=... or metadata['name'], not both"
            )
        if "model" in (metadata or {}):
            _warn_deprecated(_RECORDED_MODEL_MOVED)
        cases, forecasts = list(cases), list(forecasts)
        if len(forecasts) != len(cases):
            raise ValueError(
                f"Got {len(forecasts)} forecasts for {len(cases)} cases; pass one "
                "forecast per case, in the same order"
            )
        settings, checks = _dependence_request(
            "ForecastRun.from_forecasts", checks, old_arguments
        )
        requested = {}
        if metrics is not None:
            # Read once, so each request warns once, not once per case.
            metrics = _metric_requests(metrics)
            requested["metrics"] = _describe_metrics(metrics)
        if checks is not None:
            checks = _check_requests(checks)
            requested["checks"] = _describe_checks(checks)

        def recorded(position, case):
            if forecasts[position] is None:
                raise ValueError("No forecast was recorded for this case")
            return _as_forecast(forecasts[position], case.task)

        results = _evaluate_ready_made(cases, recorded, settings, metrics, checks)
        return cls(
            cases=results,
            metadata={
                **runtime_provenance(),
                "model": "recorded forecasts",
                "diagnostic_settings": settings,
                **requested,
                **(metadata or {}),
                **({} if name is None else {"name": name}),
            },
        )

    @property
    def report(self) -> TestReport:
        """Return the usual structured report for these evaluated cases."""
        return TestReport(
            cases=[entry._result for entry in self.cases], metadata=self.metadata
        )

    @property
    def scorecard(self):
        """The run's Scorecard: a score per kind of series and noise level, drawn as one picture.

        A run on the scorecard's kinds of series, or on patterns of your own,
        gives the usual card; a run on scenarios you built gives one row per
        scenario. Runs on ready-made cases, such as your own data, have no
        scorecard: nobody knows the answer key of real data.
        """
        card = self._card
        if card is None:
            raise ValueError(_NO_SCORECARD)
        if isinstance(card, Exception):
            raise ValueError(
                f"This run's scorecard could not be made: {card}"
            ) from card
        if callable(card):
            card = self._card = card()
        return card

    @property
    def checks(self):
        """Output checks with pass/fail counts, as in ``TestReport.checks``."""
        return self.report.checks

    @property
    def metrics(self):
        """Every case's metrics as a table, one row per case: ``TestReport.metrics`` of this run.

        Its kind and seed come first, or for your own data its name and
        where its history ends, then one column per metric. A case that
        crashed or failed an output check has NaN metrics. It reads only the
        metrics, so it works whether or not the run kept its data.
        """
        from timegym.reporting import _metrics_table

        return _metrics_table([entry._result for entry in self.cases])

    def assert_passed(self):
        """Raise AssertionError when any case crashed or failed an output check, as in ``TestReport``."""
        return self.report.assert_passed()

    def compare(
        self,
        baseline,
        *,
        metric,
        by=None,
        cluster=None,
        alpha=0.05,
        higher_is_better=False,
        seed=0,
    ):
        """Compare this run with ``baseline`` on the same cases, one metric at a time; returns a ReportComparison.

        ``result.compare(baseline, metric="mae")`` is
        ``compare_reports(result, baseline, metric="mae")``, as in
        ``TestReport.compare``: ``baseline`` is a run, or a report, made on the
        same cases in the same order. It reads only the metrics, so it works
        whether or not either run kept its data. To set several candidates
        against one baseline at once, use ``compare_reports([a, b], baseline, ...)``.
        """
        from timegym.diagnostics import compare_reports

        return compare_reports(
            self,
            baseline,
            metric=metric,
            by=by,
            cluster=cluster,
            alpha=alpha,
            higher_is_better=higher_is_better,
            seed=seed,
        )

    def calibration(self, *, bins=10, cluster=None, interval_level=0.95, seed=0):
        """How often this run's yes/no forecasts came true, and the calibration slope; returns a Calibration.

        ``result.calibration()`` is ``timegym.diagnostics.calibration(result)``.
        It reads every forecast of a 0/1 outcome, such as rain or no rain, and
        what happened, so the run must keep its data (``keep_data=True``).
        ``bins`` splits the chances into that many bins of equal width;
        ``cluster`` names a manifest key whose cases are resampled together,
        such as ``cluster="station"``; the slope's interval is at
        ``interval_level``, from bootstrap resamples drawn with ``seed``.
        ``calibration(observed, predicted)`` reads arrays instead.
        """
        from timegym.diagnostics import calibration

        return calibration(
            self, bins=bins, cluster=cluster, interval_level=interval_level, seed=seed
        )

    def to_json(self, path=None):
        """Return the report as JSON, also writing it to ``path`` when given; series stay out of it."""
        return self.report.to_json(path)

    def _set_scorecard(self, make, *, now):
        """Keep how to make the scorecard: made at once when the series are about to be dropped."""
        if not now:
            self._card = make
            return
        try:
            self._card = make()
        except Exception as exc:
            # The run stands without its scorecard; reading result.scorecard says why.
            self._card = exc

    def _drop_data(self):
        """Forget every series, answer key and forecast; metrics, checks and the scorecard stay."""
        self.cases = [
            EvaluatedCase(
                None, None, entry._result, entry.scenario_index, entry.seed_index
            )
            for entry in self.cases
        ]
        self.kept_data = False
        return self

    def _needs_data(self, what):
        if not self.kept_data:
            raise ValueError(
                f"{what} reads every series and forecast, and this run dropped them once "
                "they were scored. Run it again with keep_data=True, for example "
                "pipeline.run(..., keep_data=True)."
            )

    def plot_forecasts(self, *, show_quantiles=False, figsize=None, history=None):
        """Draw ``timegym.plotting.plot_forecasts`` for this run's retained forecasts."""
        from timegym.plotting import plot_forecasts

        self._needs_data("plot_forecasts()")
        return plot_forecasts(
            self, show_quantiles=show_quantiles, figsize=figsize, history=history
        )

    def plot_errors(
        self, metric="avoidable_mse", *, bins=None, missing="raise", figsize=None
    ):
        """Draw ``timegym.plotting.plot_errors`` for this run's retained metrics."""
        from timegym.plotting import plot_errors

        return plot_errors(
            self, metric=metric, bins=bins, missing=missing, figsize=figsize
        )


_NO_SCORECARD = (
    "This run has no scorecard. A scorecard compares each forecast with the answer key, which "
    "TimeGym knows only for the series it generates: run pipeline.run() on its kinds of series, "
    "your own patterns or scenarios you built. For your own data (cases=) and forecasts made "
    "elsewhere, read result.checks and the errors against what happened in result.metrics."
)
